const toolKey=document.body.dataset.tool,root=document.querySelector("#tool-root"),toolMeta={"image-compressor":{eyebrow:"Image Compressor",title:"Compress images with before and after preview.",description:"Upload JPG, PNG, WEBP, GIF, or SVG images, choose quality and size limits, then download optimized images or a ZIP bundle.",cardTitle:"Local canvas compression",cardText:"Images are decoded and exported in your browser. Large batches may take a moment."},"pdf-tools":{eyebrow:"PDF Tools",title:"Merge, split, optimize, and convert PDFs.",description:"Use browser libraries to merge PDFs, extract page ranges, rewrite files, turn images into PDF, or render PDF pages as PNG.",cardTitle:"PDF workbench",cardText:"PDF operations run locally with PDF-lib and PDF.js loaded from a CDN."},"background-remover":{eyebrow:"Background Cleanup",title:"Remove simple solid backgrounds and resize exports.",description:"Clean product photos with white or solid backgrounds, replace the background color, or export transparent PNGs.",cardTitle:"Best for simple backgrounds",cardText:"This browser tool samples the corner color. Complex AI cutouts need a model/API later."},"video-converter":{eyebrow:"Video Compressor",title:"Resize and record browser-supported videos.",description:"Load a video, scale it down, record a compressed WebM, extract audio when supported, or export a poster frame.",cardTitle:"Browser MediaRecorder",cardText:"Support varies by browser. WebM is the most reliable output format."},"qr-studio":{eyebrow:"QR Code Studio",title:"Generate polished QR codes for everyday sharing.",description:"Create QR codes for links, Wi-Fi, vCards, and payment text. Customize colors and download PNG or SVG.",cardTitle:"Clean exports",cardText:"The QR generator uses a proven browser QR library from a CDN."},"resume-builder":{eyebrow:"Resume Builder",title:"Build a sharp resume with live preview.",description:"Fill in focused fields, preview a clean resume, and use your browser print dialog to save as PDF.",cardTitle:"No signup, no lock-in",cardText:"Your resume content stays in the page and can be printed or exported as HTML."},"screenshot-beautifier":{eyebrow:"Screenshot Beautifier",title:"Turn raw screenshots into clean social-ready images.",description:"Add a background, padding, rounded corners, shadows, and export a polished PNG in common aspect ratios.",cardTitle:"Canvas-based export",cardText:"Perfect for product updates, portfolio shots, and social posts."}};function escapeHtml(e){return String(e??"").replace(/[&<>"']/g,(e=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#039;"}[e])))}function formatBytes(e=0){if(!e)return"0 B";const o=["B","KB","MB","GB"],r=Math.min(Math.floor(Math.log(e)/Math.log(1024)),o.length-1);return`${(e/Math.pow(1024,r)).toFixed(r?1:0)} ${o[r]}`}function blobToUrl(e){return URL.createObjectURL(e)}function downloadBlob(e,o){const r=blobToUrl(e),t=document.createElement("a");t.href=r,t.download=o,document.body.append(t),t.click(),t.remove(),setTimeout((()=>URL.revokeObjectURL(r)),1200)}function readAsDataUrl(e){return new Promise(((o,r)=>{const t=new FileReader;t.onload=()=>o(t.result),t.onerror=()=>r(t.error),t.readAsDataURL(e)}))}function readAsArrayBuffer(e){return new Promise(((o,r)=>{const t=new FileReader;t.onload=()=>o(t.result),t.onerror=()=>r(t.error),t.readAsArrayBuffer(e)}))}function loadImageFromUrl(e){return new Promise(((o,r)=>{const t=new Image;t.onload=()=>o(t),t.onerror=()=>r(new Error("Could not read this image.")),t.src=e}))}function canvasToBlob(e,o="image/png",r=.92){return new Promise((t=>{e.toBlob((e=>t(e)),o,r)}))}function safeName(e,o,r){return`${e.replace(/\.[^.]+$/,"").replace(/[^a-z0-9-_]+/gi,"-").replace(/^-|-$/g,"")||"export"}${o}.${r}`}function setStatus(e,o=""){const r=document.querySelector("[data-status]");r&&(r.className=`status ${o}`.trim(),r.textContent=e)}function renderShell(e,o){const r=toolMeta[toolKey];root.innerHTML=`\n    <section class="tool-hero">\n      <div class="tool-title">\n        <p class="eyebrow">${r.eyebrow}</p>\n        <h1>${r.title}</h1>\n        <p>${r.description}</p>\n      </div>\n      <aside class="hero-card">\n        <strong>${r.cardTitle}</strong>\n        <span>${r.cardText}</span>\n      </aside>\n    </section>\n    <section class="workspace">\n      <div class="panel">${e}</div>\n      <div class="result-panel">${o}</div>\n    </section>\n  `}function fileRows(e){return e.length?`\n    <div class="file-list">\n      ${e.map((e=>`\n        <div class="file-row">\n          <span>${escapeHtml(e.name)}</span>\n          <strong>${formatBytes(e.size)}</strong>\n        </div>\n      `)).join("")}\n    </div>\n  `:'<div class="empty-state">No files selected yet.</div>'}function outputRows(e){return e.length?`\n    <div class="output-list">\n      ${e.map(((e,o)=>`\n        <div class="output-row">\n          <span>${escapeHtml(e.name)} · ${formatBytes(e.blob.size)}</span>\n          <button class="secondary-button" type="button" data-download-output="${o}">Download</button>\n        </div>\n      `)).join("")}\n    </div>\n  `:""}function wireOutputDownloads(e){document.querySelectorAll("[data-download-output]").forEach((o=>{o.addEventListener("click",(()=>{const r=e[Number(o.dataset.downloadOutput)];r&&downloadBlob(r.blob,r.name)}))}))}
